CREATE TABLE IF NOT EXISTS finance_allocation_events ( id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, allocation_set_id BIGINT UNSIGNED NOT NULL, check_id BIGINT UNSIGNED NULL, payment_event_id BIGINT UNSIGNED NULL, event_type VARCHAR(32) NOT NULL, cash_delta_cents BIGINT NOT NULL DEFAULT 0, event_key VARCHAR(120) NOT NULL, evidence_reference VARCHAR(255) NOT NULL, created_by BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (id), UNIQUE KEY uq_fae_event (event_key), KEY ix_fae_set (allocation_set_id), CONSTRAINT fk_fae_set FOREIGN KEY (allocation_set_id) REFERENCES finance_allocation_sets(id), CONSTRAINT fk_fae_check FOREIGN KEY (check_id) REFERENCES checks(id), CONSTRAINT fk_fae_payment FOREIGN KEY (payment_event_id) REFERENCES payment_events(id), CONSTRAINT fk_fae_actor FOREIGN KEY (created_by) REFERENCES users(id) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
